INSERT INTO changelog (title, body, created_at) VALUES ('Гроші як дія: борги і нагадування', 'На Центрі в «Потребують уваги» — список боргів: клієнт, сума, скільки днів прострочено. Біля кожного (і на сторінці Гроші) кнопка «Нагадування»: відкривається «Повідомлення клієнту» одразу з шаблоном «Оплата» і сумою/датою в полі «що сказати» → Джері пише чернетку → «Копіювати» або «Мені в Telegram» (щоб переслати самому). Клієнту нічого не надсилається автоматично. Відмінки після чисел (1 оплата / 2 оплати / 5 оплат) — по всій системі через один хелпер.', datetime('now'));
